  "inlineSchema": "// Prisma schema for Better Auth\n// learn more: https://better-auth.com/docs/concepts/database\n\ngenerator client {\n  provider = \"prisma-client-js\"\n  output   = \"../generated/prisma\"\n}\n\n// NOTE: When using mysql or sqlserver, uncomment the //@db.Text annotations in model Account below\n// Further reading:\n// https://www.prisma.io/docs/reference/api-reference/prisma-schema-reference#string\n\ndatasource db {\n  provider = \"sqlite\"\n  url      = env(\"DATABASE_URL\")\n}\n\nmodel Post {\n  id        String   @id @default(cuid())\n  name      String\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  createdBy   User   @relation(fields: [createdById], references: [id])\n  createdById String\n\n  @@index([name])\n}\n\nmodel User {\n  id            String    @id\n  name          String //@db.Text\n  // Display name shown in-app (Members list, character ownership) instead\n  // of the Discord account name, if the user has set one.\n  nickname      String? //@db.Text\n  email         String\n  emailVerified Boolean   @default(false)\n  image         String? //@db.Text\n  createdAt     DateTime  @default(now())\n  updatedAt     DateTime  @default(now()) @updatedAt\n  sessions      Session[]\n  accounts      Account[]\n  posts         Post[]\n\n  createdGuilds      Guild[]\n  lastExportedGuilds Guild[]          @relation(\"GuildLastExportedBy\")\n  guildCharacters    GuildCharacter[]\n\n  @@unique([email])\n  @@map(\"user\")\n}\n\nmodel Session {\n  id        String   @id\n  expiresAt DateTime\n  token     String\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n  ipAddress String? //@db.Text\n  userAgent String? //@db.Text\n  userId    String\n  user      User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@unique([token])\n  @@map(\"session\")\n}\n\nmodel Account {\n  id                    String    @id\n  accountId             String //@db.Text\n  providerId            String //@db.Text\n  userId                String\n  user                  User      @relation(fields: [userId], references: [id], onDelete: Cascade)\n  accessToken           String? //@db.Text\n  refreshToken          String? //@db.Text\n  idToken               String? //@db.Text\n  accessTokenExpiresAt  DateTime?\n  refreshTokenExpiresAt DateTime?\n  scope                 String? //@db.Text\n  password              String? //@db.Text\n  createdAt             DateTime  @default(now())\n  updatedAt             DateTime  @updatedAt\n\n  @@map(\"account\")\n}\n\nmodel Verification {\n  id         String   @id\n  identifier String //@db.Text\n  value      String //@db.Text\n  expiresAt  DateTime\n  createdAt  DateTime @default(now())\n  updatedAt  DateTime @default(now()) @updatedAt\n\n  @@map(\"verification\")\n}\n\nmodel Guild {\n  id             String              @id @default(cuid())\n  name           String\n  discordGuildId String              @unique\n  createdById    String\n  createdBy      User                @relation(fields: [createdById], references: [id])\n  characters     GuildCharacter[]\n  requiredRoles  GuildRequiredRole[]\n  adminRoles     GuildAdminRole[]\n  createdAt      DateTime            @default(now())\n\n  // Who last generated the addon export string, and when — shown on the\n  // guild page so admins can tell if the pasted-in-game data is stale.\n  lastExportedAt   DateTime?\n  lastExportedById String?\n  lastExportedBy   User?     @relation(\"GuildLastExportedBy\", fields: [lastExportedById], references: [id])\n\n  @@index([discordGuildId])\n}\n\nmodel GuildRequiredRole {\n  id            String @id @default(cuid())\n  guildId       String\n  guild         Guild  @relation(fields: [guildId], references: [id], onDelete: Cascade)\n  discordRoleId String\n\n  @@unique([guildId, discordRoleId])\n}\n\n// Discord role IDs that grant admin rights within the app for this guild\n// (editing guild settings, viewing the raw recipe catalog) — separate from\n// requiredRoles, which only grants ordinary view/import access.\nmodel GuildAdminRole {\n  id            String @id @default(cuid())\n  guildId       String\n  guild         Guild  @relation(fields: [guildId], references: [id], onDelete: Cascade)\n  discordRoleId String\n\n  @@unique([guildId, discordRoleId])\n}\n\nmodel GuildCharacter {\n  id          String       @id @default(cuid())\n  guildId     String\n  guild       Guild        @relation(fields: [guildId], references: [id], onDelete: Cascade)\n  userId      String\n  user        User         @relation(fields: [userId], references: [id], onDelete: Cascade)\n  name        String\n  realm       String\n  // WoW class token (e.g. \"WARRIOR\") — sent by the addon's export, null for\n  // characters added through the manual entry form (createCharacter), which\n  // has no way to know it.\n  class       String?\n  importedAt  DateTime     @default(now())\n  updatedAt   DateTime     @updatedAt\n  professions Profession[]\n\n  @@unique([guildId, userId, name, realm])\n}\n\nmodel Profession {\n  id          String         @id @default(cuid())\n  characterId String\n  character   GuildCharacter @relation(fields: [characterId], references: [id], onDelete: Cascade)\n  name        String\n  recipes     Recipe[]\n\n  @@unique([characterId, name])\n}\n\nmodel Recipe {\n  id           String     @id @default(cuid())\n  professionId String\n  profession   Profession @relation(fields: [professionId], references: [id], onDelete: Cascade)\n  name         String\n  itemId       Int?\n  spellId      Int?\n\n  @@index([professionId])\n  @@index([name])\n}\n\n// Persists resolved Discord guild-member roles across server restarts.\n// Discord's /users/@me/guilds/{id}/member endpoint rate-limits hard (order\n// of minutes), and an in-memory-only cache gets wiped by every dev-server\n// reload or prod deploy, which was enough on its own to trigger repeated\n// 429s. roles is JSON-encoded (null when the user isn't a guild member).\nmodel DiscordMemberRoleCache {\n  id             String   @id @default(cuid())\n  discordGuildId String\n  userId         String\n  roles          String?\n  fetchedAt      DateTime @default(now())\n\n  @@unique([discordGuildId, userId])\n}\n\n// Caches a Discord server's own name/icon (from /users/@me/guilds, keyed by\n// whichever user's token we last used). Server-owned data, not per-viewer —\n// safe to reuse for any user, so this is keyed by discordGuildId alone.\nmodel DiscordGuildInfoCache {\n  discordGuildId String   @id\n  name           String\n  icon           String?\n  fetchedAt      DateTime @default(now())\n}\n",
